def transform(grid):
    H,W=len(grid),len(grid[0])
    def runs(row):
        out=[];cur=[]
        for v in row:
            if v: cur.append(v)
            elif cur: out.append(cur);cur=[]
        if cur: out.append(cur)
        return out
    segs=[]
    for row in grid:
        for r in runs(row):
            if len(r)>1: segs.append(r)
    loc={}
    for s in segs:
        for i,c in enumerate(s): loc[c]=(s,i)
    out=[r[:] for r in grid]
